import { Multislider } from "@/components/audio/elements/multislider";

const initialBands = [0.4, 0.7, 0.55, 0.8];

export function MultisliderHorizontalDemo() {
  return (
    <Multislider
      aria-label="Send levels"
      className="max-w-md"
      defaultValue={initialBands}
      orientation="horizontal"
      size="sm"
    />
  );
}
